package com.onlinemedic.controller;
import com.onlinemedic.model.User;import com.onlinemedic.util.Database;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.*;
@WebServlet("/review")
public class ReviewServlet extends HttpServlet{
 @Override protected void doPost(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("user");if(!"PATIENT".equals(u.role())){s.sendError(403);return;}try(Connection c=Database.getConnection()){long id=Long.parseLong(q.getParameter("appointmentId"));int rating=Integer.parseInt(q.getParameter("rating"));String comment=q.getParameter("comment");if(rating<1||rating>5||comment!=null&&comment.length()>1000)throw new IllegalArgumentException("Select 1 to 5 stars and keep the comment under 1,000 characters.");try(PreparedStatement p=c.prepareStatement("INSERT INTO reviews(appointment_id,patient_id,doctor_id,rating,comment) SELECT id,patient_id,doctor_id,?,? FROM appointments WHERE id=? AND patient_id=? AND status='COMPLETED'")){p.setInt(1,rating);p.setString(2,comment==null?"":comment.trim());p.setLong(3,id);p.setLong(4,u.id());if(p.executeUpdate()!=1)throw new IllegalArgumentException("Only one review is allowed for a completed consultation.");}try(PreparedStatement p=c.prepareStatement("UPDATE doctor_profiles SET rating=(SELECT AVG(r.rating) FROM reviews r WHERE r.doctor_id=doctor_profiles.user_id) WHERE user_id=(SELECT doctor_id FROM appointments WHERE id=?)")){p.setLong(1,id);p.executeUpdate();}q.getSession().setAttribute("flashSuccess","Thank you for rating your consultation.");s.sendRedirect(q.getContextPath()+"/appointments");}catch(IllegalArgumentException e){q.getSession().setAttribute("flashError",e.getMessage());s.sendRedirect(q.getContextPath()+"/appointments");}catch(SQLException e){if(e.getSQLState()!=null&&e.getSQLState().startsWith("23")){q.getSession().setAttribute("flashError","You have already reviewed this completed consultation.");s.sendRedirect(q.getContextPath()+"/appointments");return;}throw new ServletException("Review could not be saved.",e);}catch(Exception e){throw new ServletException("Review could not be saved.",e);}}
}
